  "implementation": "def solve(case):
    # Build node lookup and parent map
    nodes = case['nodes']
    node_by_id = {}
    parent = {}
    children = {}
    for n in nodes:
        nid = n['id']
        node_by_id[nid] = n
        p = n.get('parent')
        parent[nid] = p
        if p is not None:
            children.setdefault(p, []).append(nid)
        else:
            root_id = nid
    required_symbols = case['required_symbols']

    # Helper to get all ancestors of a node (including itself)
    def ancestors(nid):
        anc = set()
        cur = nid
        while cur is not None:
            anc.add(cur)
            cur = parent.get(cur)
        return anc

    # Start with non-removable nodes and their ancestors
    kept = set()
    for n in nodes:
        if not n['removable']:
            kept.add(n['id'])
            # add ancestors
            cur = parent.get(n['id'])
            while cur is not None:
                kept.add(cur)
                cur = parent.get(cur)

    # Ensure each required symbol appears in kept nodes
    # If not, add a removable node with that symbol and its ancestors
    for sym in required_symbols:
        # Check if already covered
        covered = any(node_by_id[nid]['symbol'] == sym for nid in kept)
        if covered:
            continue
        # Find all nodes with this symbol that are removable
        candidates = [n['id'] for n in nodes if n['symbol'] == sym and n['removable']]
        if not candidates:
            # Should not happen per problem assumption
            continue
        # Choose the candidate with the most ancestors already in kept (deepest in kept tree)
        best = max(candidates, key=lambda nid: len(ancestors(nid).intersection(kept)))
        # Add its entire ancestor chain
        kept.update(ancestors(best))

    # Build result lists
    removed_node_ids = []
    retained_node_ids = []
    for n in nodes:
        if n['id'] in kept:
            retained_node_ids.append(n['id'])
        else:
            removed_node_ids.append(n['id'])
    return {
        'removed_node_ids': removed_node_ids,
        'retained_node_ids': retained_node_ids
    }"
}
